    "profile.privacyPolicyBody": "Clinifly-ში ჩვენ უსაფრთხოდ ვინახავთ თქვენს პირად ჯანმრთელობის მონაცემებს (ფოტოები, რენტგენი, დოკუმენტები) მხოლოდ მკურნალობის მიზნებისთვის. თქვენი მონაცემები არ გაიზიარება მესამე მხარეებთან. ყველა ატვირთული სამედიცინო მონაცემი დაშიფრულია და ხელმისაწვდომია მხოლოდ თქვენი კლინიკის უფლებამოსილი თანამშრომლებისთვის.\n\nმონაცემების წაშლის მოთხოვნისთვის დაუკავშირდით თქვენს კლინიკას.",
